import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"AppMenu","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/app-menu.md","filePath":"workbench/app-menu.md"}'),d={name:"workbench/app-menu.md"};function r(h,e,i,s,c,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="appmenu" tabindex="-1">AppMenu <a class="header-anchor" href="#appmenu" aria-label="Permalink to &quot;AppMenu&quot;">​</a></h1><p>AppMenu is the menu of an application behind one button: File, Edit, View and the rest, each a submenu.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for the commands of the whole application, once per screen. The menu is a model, <code>MenuModel[]</code> (see <a href="./menu-list">MenuList</a>); its entries at the root are mostly submenus, and a few actions that are used often. The same model is the menu of the brand of a <a href="./../components/topbar">Topbar</a> (<code>menu</code>) and, on a narrow screen, a <a href="./menu-sheet">MenuSheet</a>. The actions of one item belong in a <a href="./../components/kebab">Kebab</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code></td><td>required</td><td>The model, <code>MenuModel[]</code></td></tr><tr><td><code>onselect</code></td><td></td><td>Called with the id of the chosen item</td></tr><tr><td><code>label</code></td><td>&quot;Menu&quot;</td><td>The text of the trigger, or its name with <code>icon</code></td></tr><tr><td><code>icon</code></td><td></td><td>An icon button instead of a text button</td></tr><tr><td><code>align</code></td><td><code>start</code></td><td>The edge of the trigger the menu lines up with</td></tr><tr><td><code>onOpenChange</code></td><td></td><td>Called whenever the menu opens or closes</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The trigger is a <a href="./../components/button">Button</a> with the label and a chevron, or with <code>icon</code> a ghost icon button named by the label. It opens a <a href="./../components/dropdown">Dropdown</a> menu that holds a MenuList of the model, so the keys, the submenus and the narrow width behave as a MenuList&#39;s do. Choosing an item reports its id and closes the menu. The name of the trigger is the <code>menu</code> message when no label is given.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/app-menu/" title="AppMenu" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/app-menu/" target="_blank" rel="noopener">AppMenu</a></figcaption></figure>',10)])])}const m=t(d,[["render",r]]);export{u as __pageData,m as default};
